import{_ as i,a as l,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"English 简介","description":"英语自学阶段计划、听说读写与口音选择笔记","frontmatter":{"title":"English 简介","description":"英语自学阶段计划、听说读写与口音选择笔记","sources":[{"repository":"jekyall_blog","file":"_posts/Cc/English/2023-05-17-1-english.md","date":"Sat May 16 2020 12:12:54 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"英语基础","summary":"英语自学阶段计划、听说读写与口音选择笔记","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":false,"next":{"text":"English 音标","link":"/life/english/foundations/3-phonetic_transcription"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"English 音标","link":"/life/english/foundations/3-phonetic_transcription"}},"headers":[],"relativePath":"life/english/foundations/1-english.md","filePath":"life/english/foundations/1-english.md"}'),t={name:"life/english/foundations/1-english.md"};function o(r,e,p,s,h,c){return l(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="english-简介" tabindex="-1">English 简介 <a class="header-anchor" href="#english-简介" aria-label="Permalink to &quot;English 简介&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><ul><li><p>英语是由古代日耳曼人所说的一系列语言发展而来的。最初的英语语言可以追溯到中世纪时期的英格兰和苏格兰，当时的英语被称为“古英语”或“盎格鲁-撒克逊语”。这种古老的英语语言与现代英语相比有很大的差异，包括发音、语法和词汇等方面。</p></li><li><p>在接下来的几个世纪中，英语经历了许多变迁和演变。随着时间推移和政治经济背景的变化，英语逐渐从古老的形式发展成为现代英语。在英国的文艺复兴时期（16 世纪），英语经历了重要的变革，开始借用大量拉丁语和希腊语的词汇并创造新词，这也导致了英语的词汇量不断扩大、变得更加丰富。</p></li><li><p>英语的地位在 20 世纪之后得到了进一步的提升，成为了世界上最流行的语言之一。这主要是因为英国在 19 世纪和 20 世纪大规模地进行了殖民扩张，将英语带到了全球范围内。此外，美国在 20 世纪也成为了全球经济和文化的中心，进一步推动了英语的国际化。</p></li><li><p>现在，英语是全球最重要的商务、政治、科技和文化交流语言之一。许多国际组织、学术期刊、网站和社交媒体平台都使用英语作为官方语言，而且大量的商业、法律、科技和医学文件也都是由英语编写的。</p></li></ul><h2 id="怎么学习英语-怎么去学" tabindex="-1">怎么学习英语,怎么去学 <a class="header-anchor" href="#怎么学习英语-怎么去学" aria-label="Permalink to &quot;怎么学习英语,怎么去学&quot;">​</a></h2><ol><li><p>制定计划：在开始学习英语之前，先制定一个合理的学习计划，包括每天或每周要学习多少时间、学习哪些方面的内容、达到什么样的目标等。这可以帮助您有条不紊地进行英语学习，并保持动力。</p></li><li><p>学习基础知识：在学习英语之前，需要掌握一些基础知识，如字母、基本语法规则、常见单词等。可以通过网络上的学习资源、教科书、学习应用程序等途径学习这些基础知识。</p></li><li><p>多听多说：听说是语言学习中最重要的部分。所以，在学习英语时，尽量多听真实的英语口音，可以通过听英语广播、看英语电视节目、观看英语电影等方式来提高自己的听力和口语表达能力。同时，也可以找到机会与讲英语的人交流，练习口语表达。</p></li><li><p>阅读和写作：阅读和写作对于提高英语能力同样重要。可以读英文杂志、报纸和小说，提高词汇量、语法知识和阅读理解能力；在写作方面，可以通过写日记、练习写作文等方式来加强自己的写作能力。</p></li><li><p>重视语言环境：语言环境是学习英语的一个重要因素。如果您身处英语为母语的国家或地区，那么可以主动融入当地社会、参加当地活动、结交本土朋友等方式来增强语言环境。如果没有条件去英语为母语的国家，也可以尽量让自己身处英语氛围之中，如观看英语电视节目、听英语歌曲、使用英语应用程序等。</p></li></ol><h2 id="规划和计划" tabindex="-1">规划和计划 <a class="header-anchor" href="#规划和计划" aria-label="Permalink to &quot;规划和计划&quot;">​</a></h2><h3 id="第一阶段-时间-1-个月" tabindex="-1">第一阶段（时间：1 个月） <a class="header-anchor" href="#第一阶段-时间-1-个月" aria-label="Permalink to &quot;第一阶段（时间：1 个月）&quot;">​</a></h3><ol><li><p>学习发音和基本语音规则：学习 26 个英文字母和它们的发音，了解英语基本语音规则。</p></li><li><p>词汇学习：学习 200-300 个常用单词，并记住它们的拼写和意思。可以使用英语学习应用程序或基础英语教材进行学习。</p></li><li><p>学习基本句型：学习基本的英语语法知识，如主谓宾结构、时态等，并练习几个基本句型的构造。</p></li><li><p>英语听力和口语练习：尝试与英语为母语的人交流，通过参加英语角或找到一位英语口语伙伴来提高自己的口语水平。</p></li></ol><h3 id="第二阶段-时间-3-个月" tabindex="-1">第二阶段 (时间：3 个月) <a class="header-anchor" href="#第二阶段-时间-3-个月" aria-label="Permalink to &quot;第二阶段 (时间：3 个月)&quot;">​</a></h3><ol><li><p>扩充词汇量：在前期基础上，扩充词汇量，学习 1000-1500 个常用单词，并掌握它们的用法和搭配。</p></li><li><p>学习语法和句型：深入学习英语基本语法知识，例如被动语态、条件句、疑问句等，并练习不同类型的句子构造。</p></li><li><p>阅读和写作练习：通过阅读英语文章来提高阅读理解能力，同时也可以通过写日记、对话或短文来训练自己的写作能力。</p></li><li><p>英语听力和口语练习：继续与母语人士交流，注意模仿他们的发音和表达方式，并积极参加英语活动。</p></li></ol><h3 id="第三阶段-时间-6-个月" tabindex="-1">第三阶段 (时间：6 个月) <a class="header-anchor" href="#第三阶段-时间-6-个月" aria-label="Permalink to &quot;第三阶段 (时间：6 个月)&quot;">​</a></h3><ol><li><p>高级语法和词汇：学习更高级的英语语法规则，如复合结构、间接引语等，并增加词汇量。</p></li><li><p>提高听力和口语：尝试听英语广播、看英语电影或电视剧，并积极参加英语会话，以提高听力和口语水平。</p></li><li><p>学习专业英语：根据自己的兴趣和需求，学习专业英语，掌握相关领域的术语和表达方式。</p></li><li><p>应用实践：将所学的英语知识应用到实际生活中，例如与外国朋友交流、参加英语面试等。</p></li></ol><h2 id="英音和美音选择" tabindex="-1">英音和美音选择 <a class="header-anchor" href="#英音和美音选择" aria-label="Permalink to &quot;英音和美音选择&quot;">​</a></h2><p>英式和美式英语都包含多种口音。不能按国别认定哪一种天然更清晰、准确，或一概认为一种更慢、句末固定升调。实际发音取决于说话者、地区与语境。</p><p>选择一套与教材和交流目标相符的词典录音来模仿，并保持记音约定一致；听力练习仍应接触不同口音。查词时可用 <a href="https://dictionary.cambridge.org/pronunciation/" target="_blank" rel="noopener noreferrer">Cambridge 的 UK/US 录音与音标</a>比较同一个词，关注具体声音差异，而不是把两种口音排出优劣。</p><h2 id="影视推荐" tabindex="-1">影视推荐 <a class="header-anchor" href="#影视推荐" aria-label="Permalink to &quot;影视推荐&quot;">​</a></h2><ol><li><p>《老友记》（Friends） 这是一部经典的美国情景喜剧，以六个好友之间的生活和工作为主线，讲述了各种幽默的故事情节。它的语速适中，用词简单，非常适合英语初学者观看。</p></li><li><p>《行尸走肉》（The Walking Dead） 这是一部非常流行的美国恐怖剧，描述了一个末日世界中幸存者们的生存故事。它的语言内容相对复杂，但它能提供更多的词汇和语法知识。</p></li><li><p>《发现之旅》（Discovery） 这是一部非常有趣的纪录片系列，探索了地球上的各种自然奇观和文化现象。它使用的语言相对简单，能够帮助提高听力和阅读能力。</p></li><li><p>《神探夏洛克》（Sherlock） 这是一部改编自英国作家阿瑟·柯南·道尔创作的名侦探小说的电视剧，讲述了一位神探和他的助手解决各种案件的故事。它的英语内容具有一定的难度，但是语言运用精准，对提高听力和阅读能力很有帮助。</p></li><li><p>《时空恋旅人》（Doctor Who） 这是一部英国科幻电视剧，讲述了一位时间领主和他的同伴旅行穿越时间和空间的故事。它的语言难度较高，但是对于提高听力和阅读能力和理解英国文化背景都有很大帮助。</p></li><li><p>《野性的呼唤》（Call of the Wild） 这是一部基于杰克·伦敦的同名小说改编的电影，描述了一只狗在阿拉斯加野外生存的故事。它的语言内容相对简单，适合英语初学者观看。</p></li></ol><blockquote><p>选取适合自己英语水平的影视剧或纪录片，可以在娱乐中提升英语能力。同时，配合字幕观看，有助于提高听力和阅读能力。</p></blockquote>',18)])])}const g=i(t,[["render",o]]);export{u as __pageData,g as default};
